import base64
import json
import os
from typing import Any, Dict, Optional

import requests


OPENAI_TTS_URL = "https://api.openai.com/v1/audio/speech"
OPENAI_TTS_MODEL = "gpt-4o-mini-tts"


def synthesize_text(text: str, voice: str = "alloy", format: str = "mp3", speed: float = 1.0, api_key: Optional[str] = None) -> bytes:
    if not text:
        raise ValueError("text must not be empty")
    if not voice:
        raise ValueError("voice must not be empty")
    if not format:
        raise ValueError("format must not be empty")

    key = api_key or os.getenv("OPENAI_API_KEY")
    if not key:
        raise RuntimeError("OPENAI_API_KEY is required")

    payload: Dict[str, Any] = {
        "model": OPENAI_TTS_MODEL,
        "input": text,
        "voice": voice,
        "format": format,
        "speed": speed,
    }

    response = requests.post(
        OPENAI_TTS_URL,
        headers={
            "Authorization": f"Bearer {key}",
            "Content-Type": "application/json",
        },
        data=json.dumps(payload),
        timeout=120,
    )
    response.raise_for_status()
    return response.content


def synthesize_text_base64(text: str, voice: str = "alloy", format: str = "mp3", speed: float = 1.0, api_key: Optional[str] = None) -> str:
    return base64.b64encode(synthesize_text(text, voice=voice, format=format, speed=speed, api_key=api_key)).decode("ascii")

import os
from typing import Any, Dict, List, Optional

import requests


OPENAI_API_BASE = "https://api.openai.com/v1"


def _auth_headers() -> Dict[str, str]:
    api_key = os.getenv("OPENAI_API_KEY")
    if not api_key:
        raise RuntimeError("OPENAI_API_KEY is required")
    return {"Authorization": f"Bearer {api_key}"}


def list_voices() -> List[Dict[str, Any]]:
    response = requests.get(f"{OPENAI_API_BASE}/audio/voices", headers=_auth_headers(), timeout=30)
    response.raise_for_status()
    payload = response.json()
    if isinstance(payload, dict) and "data" in payload and isinstance(payload["data"], list):
        return payload["data"]
    if isinstance(payload, list):
        return payload
    raise RuntimeError("Unexpected voice list response format")


def select_voice(target_locale: str, voices: Optional[List[Dict[str, Any]]] = None) -> Dict[str, Any]:
    target = target_locale.strip().lower().replace("_", "-")
    candidates = voices if voices is not None else list_voices()
    exact = []
    prefix = []
    fallback = []
    for voice in candidates:
        locale = str(voice.get("locale", "")).strip().lower().replace("_", "-")
        if not locale:
            fallback.append(voice)
        elif locale == target:
            exact.append(voice)
        elif locale.startswith(target.split("-")[0]):
            prefix.append(voice)
        elif target.startswith(locale.split("-")[0]):
            prefix.append(voice)
    if exact:
        return exact[0]
    if prefix:
        return prefix[0]
    if fallback:
        return fallback[0]
    raise LookupError(f"No voice found for locale: {target_locale}")


__all__ = ["list_voices", "select_voice"]

